The lemma follows easily by applying the formula, for $(k, b) = 1$,
\begin{equation} \label{orthprope}
\begin{split}
e^{- 2\pi i a k /b} 
&
=
\sum_{1 \leq x \leq b}e^{-2\pi i a x / b}
\sum_{\chi:(\mathbb{Z} / b)^{*} \to \mathbb{C}^{*}} \frac{\chi(k)\overline{\chi}(x)}{\phi(b)}
\\
& = \sum_{\chi} \chi(k)
\frac{\sum_{1 \leq x \leq b} \overline{\chi}(x) e^{- 2 \pi i a x / b}   }{\phi(b)} \\
& =  \sum_{\chi} \chi(k) A(a, b; \chi),
\end{split}
\end{equation}
which can be easily shown with the well-known identity concerning
Dirichlet characters valid for $(a, m) = 1$ \cite{H}
\[
\frac{\sum_{\chi \in (\mathbb{Z} / m)^{*}} \overline{\chi}(x) \chi(a)  }{\phi(m)}
= 
\begin{cases}
1   &  x \equiv a \text{(mod $m$)}, \\
0   &  \text{otherwise};
\end{cases}
\]
here, for each $k$,
there exists only one $1 \leq k' \leq q$
which is equal to $k$ modulo $q$
so that the sum of (\ref{orthprope}) is equal to $e^{- 2\pi i a k' / q} = e^{- 2\pi i a k / q}$.

We rewrite
\[
\begin{split}
-  \sum_{\chi}  A(a, b; \chi) \frac{L'}{L}(s, \chi)
& =  \sum_{\chi}  A(a, b; \chi)  \sum_{n \geq 1} 
\frac{
\Lambda(n)  \chi(n)
}{n^{s}} \\
&  = \sum_{n \geq 1} \frac{\Lambda(n)}{n^{s}}
 \sum_{1 \leq x \leq b} e^{-2 \pi i a x/b} \sum_{\chi} \frac{\overline{\chi}(x) \chi(n)}{\phi(b)}.
\end{split}
\]

By the fact that the formula (\ref{orthprope}) is applicable to all $n$'s which are powers of primes other than of $q|b$,
we have
\[
M(s, a/b) - \sum_{q|b} \sum_{l \geq 1} (\log q) q^{-sl} e^{- 2 \pi i a q^{l}/b}
 = -  \sum_{\chi}  A(a, b; \chi) \frac{L'}{L}(s, \chi).
\]
This completes the proof of the lemma.

\label{main1}
Let $0 < c <1$, $\delta > 0$, $c + \delta + \kappa > 1$, $c' > 0$, $\kappa - c' > 1$, $\delta + c' > 1$, 
and $p$ be any real numbers satisfying $0 < p < 1$.
Then we have
\begin{equation} \label{thm1}
\begin{split}
& \frac{1}{2\pi i}\int_{(c)} 
\sum_{n \geq 2} \frac{\Lambda(n) e^{-2 \pi i p n} }{
n^{s + \delta + \kappa}}
\Gamma(s) \Gamma(s+ \delta)\Gamma(1-s) (2 p\pi)^{-s}e^{-\pi i s / 2}ds \\
& = \Gamma(1 + \delta)
(- \frac{\zeta'}{\zeta}(\kappa))
[ (2 \pi p)^{-\delta}  e^{\delta \pi i / 2}\Gamma( - \delta)
+ K(p, 1 + \delta)]
\\
& -  \frac{\Gamma(1 + \delta)}{2 \pi i }
\int_{c' - i \infty}^{c' + i\infty}
- \frac{\zeta'}{\zeta}
(\kappa - w) \\
& \times 
 [(2 \pi p)^{-\delta - w}  e^{(\delta + w ) \pi i / 2}\Gamma( - \delta - w)
+ K(p, 1 + \delta + w)]
\frac{dw}{w}.
\end{split}
\end{equation}
where $K(p, \xi)$ denotes a function defined for $0 < \text{Re}(\xi) < 1$ by
\[
K(p, \xi) \equiv - \int_{0}^{1} e^{- 2 \pi i p r } r^{-\xi} ds.
\]

\label{claim}
Suppose that $M(s, p)$ has a pole at  $s = \rho_{n_{1}, p} = 1/2 + \eta_{n_{1}, p} + i \gamma_{n_{1}, p}$
with $\eta_{n_{1}, p} > 0$ and $p = a/b < 1$ is any rational number satisfying $b \ll \log \gamma_{n_{1}, p}$.
Let $\nu > 0$ be arbitrary and
\[
R_{n_{1}, p} \equiv \{a + bi \in \mathbb{C}: 1/2 \leq a \leq 1, 
|b| \leq A \log \gamma_{n_{1}, p}  \}
\]
for some absolute constant $A$ which is independent of $\rho_{n_{1}, p}$.
Suppose also that
$\eta_{n_{1}, p}$ is the largest number among other such numbers
associated with other
possible zeros of $L(s, \chi)$'s off the criticial line, at which
$M(s, p)$ may have poles in $R_{n_{1}, p}$.
Then, we have as $\gamma_{n_{1}, p} \to \infty$,
\begin{equation} \label{mode11}
\begin{split}
& c(p) \Gamma( \rho_{n_{1}, p} ) e^{\pi \gamma_{n_{1}, p}/ 2} \\
& \sim
\Gamma(1 + \nu + i \gamma_{n_{1}, p})e^{\pi \gamma_{n_{1}, p}/ 2}   \\
& \times 
\sum_{\rho_{j}}
\rho_{j}^{-1}
 (2 \pi p)^{- \nu - i \gamma_{n_{1}, p} + \rho_{j} }  e^{(\nu + i \gamma_{n_{1}, p} - \rho_{j}  ) \pi i / 2}\Gamma(
- \nu - i \gamma_{n_{1}, p} + \rho_{j}),
\end{split}
\end{equation}
where
\[
\begin{split}
c(p) 
& \equiv 
 (2 p \pi)^{-1/2 - \eta_{n_{1}, p} 
+ \nu }
e^{-\pi i (1/2 +  \eta_{n_{1}, p}  - \nu) / 2} \\
& \times \Gamma(
1/2 +  \eta_{n_{1}, p}  - \nu
)
\Gamma(1/2 -  \eta_{n_{1}, p} + \nu )
c_{\rho_{n_{1}, p}} 
\end{split}
\]
and $c_{\rho_{n_{1}, p}}$ is the residue of $M(s, p)$ at $s = \rho_{n_{1}, p}$.  

In addition,
the expression on the right side of (\ref{mode11}) is continuous in $p \in (0, 1)$.

\label{conjecture}
For arbitrary $\epsilon > 0$, we have
\[
\sum_{\chi} A(a, b; \chi) \sum_{|t - \gamma| < 1} \frac{1}{s - \rho_{\chi}}
\ll t^{\epsilon}
\]
as $t \to \infty$, with the absolute constant independent of $b$.
